head.b:skin:
/* ========================================================
   SUNTIKAN ANTI-BOCOR: MEMBERSIHKAN ELEMEN BAWAAN BLOGGER
   ======================================================== */
#header-wrapper, .header-outer, #sidebar-wrapper, .sidebar-outer,
#footer-wrapper, .footer-outer, .post-footer, .feed-links,
.comments, #blog-pager, .status-msg-wrap, .attribution,
.blog-feeds, .report_abuse, .SearchThisBlog, #BlogSearch1,
.footer, .post-feeds, #blog-pager, .breadcrumbs, .nav,
.widget-item-control, .avatar-image-container {
    display: none !important;
    visibility: hidden !important;
    height: 0 !important;
    padding: 0 !important;
    margin: 0 !important;
}

.main-inner, .date-header, .post-title, .post-body, .blog-posts,
.main-outer, .columns, .fauxcolumn-left-outer, .fauxcolumn-right-outer {
    background: none !important;
    border: none !important;
    box-shadow: none !important;
    padding: 0 !important;
    margin: 0 !important;
}

body { 
    margin: 0 !important; 
    padding: 0 !important; 
    background: #f8fafc !important; 
    font-family: 'Inter', sans-serif; 
}

b:includable.script:
//

function toggleFormLock() {
    const txtArea = document.getElementById('user-thought');
    const btn = document.getElementById('btn-lock-save');
    txtArea.disabled = !txtArea.disabled;
    btn.innerHTML = txtArea.disabled ? "✏️ EDIT DATA" : "🔒 SIMPAN DATA";
    btn.className = txtArea.disabled ? "btn-action btn-edit" : "btn-action btn-save";
}

function resetForm() {
    document.getElementById('user-thought').value = "";
    document.getElementById('user-thought').disabled = false;
    document.getElementById('btn-lock-save').innerHTML = "🔒 SIMPAN DATA";
    document.getElementById('btn-lock-save').className = "btn-action btn-save";
    document.getElementById('status-msg').innerHTML = "🔄 Formulir input telah dikosongkan.";
}

function action(type) {
    const care = document.getElementById('care-selector').value;
    const mode = document.getElementById('mode-selector').value;
    const thought = document.getElementById('user-thought').value.trim();
    const status = document.getElementById('status-msg');

    let baseInstruction = "Bertindaklah sebagai Konsultan & Pakar Medis Spesialis Kedokteran Paliatif Senior (merujuk pada Oxford Textbook of Palliative Medicine).\n";
    baseInstruction += "Saya ingin Anda menyusun sebuah modul masterclass tingkat tinggi dengan fokus utama pada layanan: \"" + care + "\".\n\n";

    // INTEGRASI LOGIS KASUS USER
    if (thought) {
        baseInstruction += "🚨 PRIORITAS UTAMA ANALISIS - INTEGRASIKAN KASUS/POKOK PIKIRAN INI:\n";
        baseInstruction += "Anda wajib mengaitkan, menerapkan, dan menguji teori pengajaran Anda langsung pada skenario/pokok pikiran berikut: \"" + thought + "\"\n\n";
    }

    // PRESENTATION BLUEPRINT DIRECTIVE
    baseInstruction += "⚠️ PRESENTATION BLUEPRINT DIRECTIVE:\n";
    baseInstruction += "Sajikan seluruh jawaban pembahasan Anda dalam kerangka 'Naskah Slide Presentasi PowerPoint (PPTx)' demi kenyamanan saya menyalin materi ke media visual. Pecah output menjadi rancangan per-slide (Slide 1, Slide 2, dst.), di mana tiap slide memuat komponen:\n";
    baseInstruction += "  - [Judul Slide]: Judul presentasi yang ringkas, tegas, dan berwibawa.\n";
    baseInstruction += "  - [Isi Slide / Bullet Points]: Maksimal 4-5 poin ringkas, padat, mendalam, dan berbasis bukti (evidence-based).\n";
    baseInstruction += "  - [Visual Cue]: Saran konsep gambar konkrit, bagan alur patofisiologi, tabel dosis, atau grafik klinis pendukung yang relevan untuk memperkuat estetika slide.\n\n";

    baseInstruction += "Lakukan pendekatan 'Deep Dive' yang seluas samudra, lengkap, rinci, terstruktur, matang, dan berbasis bukti untuk setiap rancangan slide.\n\n";

    let continuityRule = "\n\nCRITICAL RULE UNTUK GEMINI:\nJangan mengakhiri sesi atau menyimpulkan materi secara final di satu respons ini saja. ";
    continuityRule += "Pada akhir output Anda, WAJIB berikan 'Prompt Hook' berupa pertanyaan terbuka atau opsi sub-topik lanjutan yang spesifik untuk melangkah ke slide evaluasi/pendalaman berikutnya, lalu instruksikan saya untuk mengetik 'Lanjut'.";

    // KONSTRUKSI STRUKTUR KELUARAN MODE SELECTOR
    let modeConstraint = "";
    if(mode === 'pro') {
        modeConstraint = "STRUKTUR OUTPUT MODE PRO (DEEP DIVE SLIDE ARCHITECT):\n" +
                         "Sajikan visualisasi naskah slide yang membedah:\n" +
                         "1. LATAR BELAKANG & EPIDEMIOLOGI: Analisis urgensi klinis topik ini pada pasien stadium terminal.\n" +
                         "2. TEORI & PATOFISIOLOGI GEJALA: Mekanisme biologis, psikososial, dan spiritual secara mendalam.\n" +
                         "3. PROTOKOL IMPLEMENTASI KLINIS: Algoritma manajemen taktis (utamakan rute Subkutan/SC, hindari Intramuskular/IM), serta titrasi dosis farmakologi.\n" +
                         "4. ILUSTRASI KASUS NYATA: Narasi skenario riil pasien kompleks (multimorbiditas).\n" +
                         "5. BANK EVALUASI KOMPREHENSIF PART 1: Tuliskan 10-20 soal pilihan ganda berbasis kasus klinis (Vignette Case) tingkat tinggi (HOTs) lengkap dengan Kunci Jawaban dan Rasional Medis.\n\n";
    } else if(mode === 'story') {
        modeConstraint = "STRUKTUR OUTPUT MODE KISAH ILUSTRASI BERKELANJUTAN (NARATIF INTERAKTIF SLIDE):\n" +
                         "Sajikan visualisasi naskah slide dengan alur:\n" +
                         "1. Babak pertama dari Kisah Ilustrasi Naratif berbobot tinggi mengenai pasien paliatif dengan dinamika penyakit kompleks dan konflik internal keluarga.\n" +
                         "2. Integrasi teori patofisiologi kedokteran dan protokol manajemen gejala secara organik ke dalam alur narasi slide.\n" +
                         "3. Di akhir slide babak ini, ajukan 3 pertanyaan reflektif-klinis kritis yang dilematis terkait langkah penatalaksanaan berikutnya untuk memicu respons interaktif.\n\n";
    } else {
        modeConstraint = "STRUKTUR OUTPUT VERSI STANDAR (SLIDE OUTLINE):\n" +
                         "Sajikan visualisasi naskah slide yang berisi:\n" +
                         "1. Rangkuman Teori Esensial & Implementasi Klinis Praktis.\n" +
                         "2. 1 Ilustrasi Kasus Singkat.\n" +
                         "3. 3 Soal Evaluasi Vignette Klinis beserta Kunci Jawaban dan pembahasan rasional medis.\n\n";
    }

    // PENENTUAN MATERI BERDASARKAN TOMBOL YANG DIPILIH
    let topicPrompt = "";
    if(type === "infinite") {
        topicPrompt = "ARAHAN TOPIK MODUL: Aktifkan mode INFINITE DRILL. Berikan 1 soal studi kasus klinis tingkat lanjut secara acak dari seluruh spektrum keilmuan kurikulum Oxford. ";
        topicPrompt += "Setelah saya menjawab, jabarkan pembahasannya dalam struktur rancangan slide, berikan koreksi berbasis pedoman internasional, bedah rasional teorinya, lalu secara otomatis berikan 1 soal baru berikutnya.";
    } else if(type === "story_mode") {
        topicPrompt = "ARAHAN TOPIK MODUL: Aktifkan MODE KISAH ILUSTRASI NARATIF (UMUM). Jalankan naratif interaktif komprehensif spektrum luas mengenai penanganan kasus paliatif makro-mikro.\n" +
                      "Strukturkan output dalam format rancangan naskah slide presentasi, gabungkan teori-teori klinis Oxford secara implisit ke dalam plot drama medis, dan akhiri dengan 3 pertanyaan dilematis penentu keputusan tindakan.";
    } else {
        const topics = {
            "sec1": "BAGIAN 1: Global Policy & Ethics (Perspektif Makro)\n" +
                    "- The Worldwide Status: Analisis kemajuan perawatan paliatif global dan pemetaan Global Atlas of Palliative Care.\n" +
                    "- Human Rights & Access: Advokasi akses obat esensial (Opioid) dan integrasi paliatif sebagai hak asasi manusia fundamental.\n" +
                    "- Health Economics: Analisis efektivitas biaya (cost-effectiveness) dan kebijakan kesehatan publik dalam integrasi layanan paliatif nasional.",

            "sec2": "BAGIAN 2: Foundations of Palliative Medicine\n" +
                    "- Core Concepts: Definisi, filosofi, dan epidemiologi penyakit kronis progresif.\n" +
                    "- Cultural & Bioethical Dimensions: Pengaruh etnisitas, kepercayaan, dan budaya terhadap persepsi sakit, serta navigasi dilema etis di akhir hayat.",

            "sec3": "BAGIAN 3: Service Delivery & Models of Care\n" +
                    "- Integrated Care: Model integrasi dini (early integration) paliatif pada onkologi dan non-onkologi.\n" +
                    "- Care Settings: Strategi layanan di berbagai tatanan: Komunitas (Homecare), Rumah Sakit (Hospice/Palliative Unit), dan Unit Gawat Darurat.",

            "sec4": "BAGIAN 4: The Interdisciplinary Team (IDT)\n" +
                    "- Clinical Roles: Sinergi peran dokter spesialis, perawat paliatif, dan tenaga kesehatan tambahan (farmasi klinis, fisioterapi).\n" +
                    "- Holistic Support: Integrasi dukungan psikososial, konseling medik, dan pemenuhan kebutuhan spiritualitas pasien.",

            "sec5": "BAGIAN 5: Communication & Advance Care Planning (ACP)\n" +
                    "- Clinical Communication: Teknik komunikasi efektif (misal: protokol SPIKES) dalam penyampaian berita buruk dan manajemen konflik.\n" +
                    "- Advance Care Planning: Dokumentasi preferensi medis, Living Will, dan penunjukan pengambil keputusan pengganti (Surrogate decision-maker).",

            "sec6": "BAGIAN 6: Family & Caregiver Dynamics\n" +
                    "- Family Systems: Memahami dinamika keluarga dalam menghadapi penyakit terminal.\n" +
                    "- Caregiver Burden: Instrumen penilaian beban pengasuh dan strategi intervensi untuk mencegah burnout.",

            "sec7": "BAGIAN 7: Pain Management (Deep Dive)\n" +
                    "- Physiology of Pain: Neurobiologi nyeri kronis dan klasifikasi (Nositif, Neuropatik, Nyeri Kanker).\n" +
                    "- Pharmacotherapy: Prinsip tangga analgesik WHO, manajemen opioid (titrasi, rotasi, efek samping), dan ko-analgesik.\n" +
                    "- Specialist Interventions: Manajemen nyeri viseral, nyeri tulang metastatik, dan pendekatan nyeri pada populasi pediatrik.",

            "sec8": "BAGIAN 8: Symptom Control (Non-Pain)\n" +
                    "- Gastrointestinal: Patofisiologi mual-muntah (CINV), konstipasi opioid, obstruksi usus maligna, dan kaheksia-anoreksia.\n" +
                    "- Cardiorespiratory & Others: Manajemen dispnea terminal, batuk kronis, kegagalan organ, serta gejala neurologis/genitourinaria.",

            "sec9": "BAGIAN 9: End-of-Life Care & Special Populations\n" +
                    "- Terminal Phase: Identifikasi fase dying, penggunaan sedasi paliatif proporsional, dan manajemen kedaruratan terminal.\n" +
                    "- Special Populations: Protokol khusus untuk pediatrik, geriatri, pasien gagal ginjal kronis (ESRD), gagal jantung, serta pasien HIV/AIDS.\n" +
                    "- Bereavement Support: Manajemen duka cita bagi keluarga pasca-kematian (duka normal vs patologis)."
        };
        topicPrompt = "ARAHAN TOPIK MODUL: " + topics[type];
    }

    // INTEGRASI AKHIR ELEMEN GENERATOR
    let finalPrompt = baseInstruction + modeConstraint + topicPrompt + continuityRule;

    // Eksekusi Clipboard dan Pengalihan halaman
    navigator.clipboard.writeText(finalPrompt).then(function() {
        status.innerHTML = "🚀 <b>Mega-Prompt PPTx Injected Berhasil Disalin!</b> Mengalihkan ke Gemini...";
        setTimeout(function() {
            window.open('https://gemini.google.com/', '_blank');
        }, 900);
    }).catch(function(err) {
        status.innerText = "Gagal menyalin secara otomatis. Silakan periksa izin clipboard browser Anda.";
    });
}
//
